// ──────────────────────────── tests ──────────────────────────────────────

// ── stage 1: on / emit ───────────────────────────────────────────────────

test('on registers a listener that emit calls', () => {
  const bus = new EventEmitter();
  const heard = spy();
  bus.on('ping', heard);
  bus.emit('ping');
  eq(heard.callCount, 1);
});

test('emit forwards every argument to the listener', () => {
  const bus = new EventEmitter();
  const heard = spy();
  bus.on('data', heard);
  bus.emit('data', 1, 'two', { three: 3 });
  eq(heard.calls[0], [1, 'two', { three: 3 }]);
});

test('listeners run in the order they were registered', () => {
  const bus = new EventEmitter();
  const order = [];
  bus.on('go', () => order.push('a'));
  bus.on('go', () => order.push('b'));
  bus.on('go', () => order.push('c'));
  bus.emit('go');
  eq(order, ['a', 'b', 'c']);
});

test('emitting an event nobody listens to returns false', () => {
  const bus = new EventEmitter();
  eq(bus.emit('nothing', 1), false);
});

test('emit returns true when at least one listener ran', () => {
  const bus = new EventEmitter();
  bus.on('hit', () => {});
  eq(bus.emit('hit'), true);
});

test('listenerCount counts the listeners of one event', () => {
  const bus = new EventEmitter();
  bus.on('a', () => {});
  bus.on('a', () => {});
  bus.on('b', () => {});
  eq(bus.listenerCount('a'), 2);
  eq(bus.listenerCount('never-used'), 0);
});

// ── stage 2: off / once ──────────────────────────────────────────────────

test('off removes exactly one listener', () => {
  const bus = new EventEmitter();
  const a = spy();
  const b = spy();
  bus.on('x', a);
  bus.on('x', b);
  bus.off('x', a);
  bus.emit('x');
  eq(a.callCount, 0);
  eq(b.callCount, 1);
});

test('off with a listener that was never added is a no-op', () => {
  const bus = new EventEmitter();
  const a = spy();
  bus.on('x', a);
  bus.off('x', () => {});
  bus.off('never-used', a);
  bus.emit('x');
  eq(a.callCount, 1);
});

test('once fires on the first emit only', () => {
  const bus = new EventEmitter();
  const a = spy();
  bus.once('boot', a);
  bus.emit('boot');
  bus.emit('boot');
  bus.emit('boot');
  eq(a.callCount, 1);
});

test('once forwards arguments just like on', () => {
  const bus = new EventEmitter();
  const a = spy();
  bus.once('boot', a);
  bus.emit('boot', 'fast', 42);
  eq(a.calls[0], ['fast', 42]);
});

test('a once listener is unregistered before it runs', () => {
  const bus = new EventEmitter();
  bus.once('boot', () => {});
  eq(bus.listenerCount('boot'), 1);
  bus.emit('boot');
  eq(bus.listenerCount('boot'), 0);
});

test('off cancels a once listener by its original function', () => {
  const bus = new EventEmitter();
  const a = spy();
  bus.once('boot', a);
  bus.off('boot', a);
  bus.emit('boot');
  eq(a.callCount, 0);
});

// ── stage 3: on() returns an unsubscribe function ────────────────────────

test('on returns a function that removes the listener', () => {
  const bus = new EventEmitter();
  const a = spy();
  const stop = bus.on('x', a);
  ok(typeof stop === 'function');
  bus.emit('x');
  stop();
  bus.emit('x');
  eq(a.callCount, 1);
});

test('the unsubscribe function is safe to call twice', () => {
  const bus = new EventEmitter();
  const a = spy();
  const b = spy();
  const stop = bus.on('x', a);
  bus.on('x', b);
  stop();
  stop();
  bus.emit('x');
  eq(a.callCount, 0);
  eq(b.callCount, 1);
});

test('once also returns a working unsubscribe', () => {
  const bus = new EventEmitter();
  const a = spy();
  const stop = bus.once('boot', a);
  stop();
  bus.emit('boot');
  eq(a.callCount, 0);
  eq(bus.listenerCount('boot'), 0);
});

// ── stage 4: wildcards and robustness ────────────────────────────────────

test("a '*' listener hears every event", () => {
  const bus = new EventEmitter();
  const all = spy();
  bus.on('*', all);
  bus.emit('one');
  bus.emit('two');
  eq(all.callCount, 2);
});

test("a '*' listener receives the event name, then the args", () => {
  const bus = new EventEmitter();
  const all = spy();
  bus.on('*', all);
  bus.emit('save', { id: 1 }, 'now');
  eq(all.calls[0], ['save', { id: 1 }, 'now']);
});

test('specific listeners run before wildcard listeners', () => {
  const bus = new EventEmitter();
  const order = [];
  bus.on('*', () => order.push('star'));
  bus.on('save', () => order.push('save'));
  bus.emit('save');
  eq(order, ['save', 'star']);
});

test('a listener that throws does not stop the ones after it', () => {
  const bus = new EventEmitter();
  const order = [];
  bus.on('x', () => order.push('first'));
  bus.on('x', () => {
    throw new Error('boom');
  });
  bus.on('x', () => order.push('third'));
  eq(bus.emit('x'), true);
  eq(order, ['first', 'third']);
});

test('onError receives the error and the event name', () => {
  const seen = [];
  const bus = new EventEmitter({
    onError: (err, event) => seen.push([err.message, event]),
  });
  bus.on('x', () => {
    throw new Error('boom');
  });
  bus.emit('x');
  eq(seen, [['boom', 'x']]);
});

test('removing a listener during emit does not skip the next one', () => {
  const bus = new EventEmitter();
  const order = [];
  const b = () => order.push('b');
  bus.on('t', () => {
    order.push('a');
    bus.off('t', b);
  });
  bus.on('t', b);
  bus.on('t', () => order.push('c'));
  bus.emit('t');
  eq(order, ['a', 'b', 'c']);
  bus.emit('t');
  eq(order, ['a', 'b', 'c', 'a', 'c']);
});

// ──────────────────────────── tests ──────────────────────────────────────

// ── stage 1: get / set / subscribe ───────────────────────────────────────

test('get returns the initial state', () => {
  const store = createStore({ n: 0 });
  eq(store.get(), { n: 0 });
});

test('set shallow-merges a partial patch', () => {
  const store = createStore({ n: 0, name: 'ada' });
  store.set({ n: 7 });
  eq(store.get(), { n: 7, name: 'ada' });
});

test('set replaces the state object instead of mutating it', () => {
  const initial = { n: 0 };
  const store = createStore(initial);
  store.set({ n: 1 });
  eq(initial, { n: 0 });
  ok(store.get() !== initial);
});

test('subscribers are called with the next and previous state', () => {
  const store = createStore({ n: 0 });
  const seen = [];
  store.subscribe((next, prev) => seen.push([next.n, prev.n]));
  store.set({ n: 1 });
  store.set({ n: 2 });
  eq(seen, [
    [1, 0],
    [2, 1],
  ]);
});

test('subscribe returns a working unsubscribe function', () => {
  const store = createStore({ n: 0 });
  let calls = 0;
  const stop = store.subscribe(() => (calls += 1));
  store.set({ n: 1 });
  stop();
  store.set({ n: 2 });
  eq(calls, 1);
});

test('every subscriber hears about a change', () => {
  const store = createStore({ n: 0 });
  const seen = [];
  store.subscribe(() => seen.push('a'));
  store.subscribe(() => seen.push('b'));
  store.set({ n: 1 });
  eq(seen, ['a', 'b']);
});

// ── stage 2: updater functions and silent no-op writes ───────────────────

test('set accepts an updater function of the current state', () => {
  const store = createStore({ n: 1 });
  store.set((s) => ({ n: s.n + 1 }));
  store.set((s) => ({ n: s.n + 1 }));
  eq(store.get(), { n: 3 });
});

test('the updater sees every other key too', () => {
  const store = createStore({ first: 'Ada', last: 'Lovelace' });
  store.set((s) => ({ full: `${s.first} ${s.last}` }));
  eq(store.get().full, 'Ada Lovelace');
});

test('shallowEqual compares one level deep with Object.is', () => {
  eq(shallowEqual({ a: 1 }, { a: 1 }), true);
  eq(shallowEqual({ a: 1 }, { a: 2 }), false);
  eq(shallowEqual({ a: 1 }, { a: 1, b: 2 }), false);
  eq(shallowEqual({ a: {} }, { a: {} }), false);
});

test('writing the value a key already has notifies nobody', () => {
  const store = createStore({ n: 0, name: 'ada' });
  let calls = 0;
  store.subscribe(() => (calls += 1));
  store.set({ n: 0 });
  store.set({ name: 'ada' });
  store.set((s) => ({ n: s.n }));
  eq(calls, 0);
});

test('a no-op write keeps the very same state object', () => {
  const store = createStore({ n: 0 });
  const before = store.get();
  store.set({ n: 0 });
  ok(store.get() === before);
});

test('an equal-looking new object still counts as a change', () => {
  const store = createStore({ user: { name: 'ada' } });
  let calls = 0;
  store.subscribe(() => (calls += 1));
  store.set({ user: { name: 'ada' } });
  eq(calls, 1);
});

// ── stage 3: computed values ─────────────────────────────────────────────

test('computed derives a value from the current state', () => {
  const store = createStore({ items: [1, 2, 3] });
  const count = computed(store, (s) => s.items.length);
  eq(count.get(), 3);
});

test('computed is up to date after the store changes', () => {
  const store = createStore({ items: [1, 2, 3] });
  const count = computed(store, (s) => s.items.length);
  store.set({ items: [1] });
  eq(count.get(), 1);
});

test('computed notifies subscribers with the new and old value', () => {
  const store = createStore({ n: 1 });
  const doubled = computed(store, (s) => s.n * 2);
  const seen = [];
  doubled.subscribe((next, prev) => seen.push([next, prev]));
  store.set({ n: 5 });
  eq(seen, [[10, 2]]);
});

test('computed stays quiet when its own value did not change', () => {
  const store = createStore({ n: 1, unrelated: 'a' });
  const doubled = computed(store, (s) => s.n * 2);
  let calls = 0;
  doubled.subscribe(() => (calls += 1));
  store.set({ unrelated: 'b' });
  store.set({ unrelated: 'c' });
  eq(calls, 0);
  eq(doubled.get(), 2);
});

test('unsubscribing from a computed stops the notifications', () => {
  const store = createStore({ n: 1 });
  const doubled = computed(store, (s) => s.n * 2);
  let calls = 0;
  const stop = doubled.subscribe(() => (calls += 1));
  store.set({ n: 2 });
  stop();
  store.set({ n: 3 });
  eq(calls, 1);
});

// ── stage 4: batching ★ ──────────────────────────────────────────────────

test('batch turns several writes into one notification', () => {
  const store = createStore({ a: 0, b: 0 });
  let calls = 0;
  store.subscribe(() => (calls += 1));
  batch(() => {
    store.set({ a: 1 });
    store.set({ b: 2 });
    store.set({ a: 3 });
  });
  eq(calls, 1);
});

test('the one notification carries the final state', () => {
  const store = createStore({ a: 0, b: 0 });
  const seen = [];
  store.subscribe((next, prev) => seen.push([next, prev]));
  batch(() => {
    store.set({ a: 1 });
    store.set({ b: 2 });
  });
  eq(seen, [[{ a: 1, b: 2 }, { a: 0, b: 0 }]]);
});

test('reads inside a batch see the writes immediately', () => {
  const store = createStore({ n: 0 });
  const inside = [];
  batch(() => {
    store.set({ n: 1 });
    inside.push(store.get().n);
    store.set((s) => ({ n: s.n + 1 }));
    inside.push(store.get().n);
  });
  eq(inside, [1, 2]);
  eq(store.get().n, 2);
});

test('batch returns whatever its callback returned', () => {
  const store = createStore({ n: 0 });
  const out = batch(() => {
    store.set({ n: 1 });
    return 'done';
  });
  eq(out, 'done');
});

test('a batch that changes nothing notifies nobody', () => {
  const store = createStore({ n: 0 });
  let calls = 0;
  store.subscribe(() => (calls += 1));
  batch(() => {
    store.set({ n: 0 });
  });
  eq(calls, 0);
});

test('nested batches flush only when the outermost one exits', () => {
  const store = createStore({ n: 0 });
  let calls = 0;
  store.subscribe(() => (calls += 1));
  batch(() => {
    store.set({ n: 1 });
    batch(() => {
      store.set({ n: 2 });
    });
    eq(calls, 0);
  });
  eq(calls, 1);
  eq(store.get().n, 2);
});

test('a batch that throws still flushes the writes it made', () => {
  const store = createStore({ n: 0 });
  const seen = [];
  store.subscribe((next) => seen.push(next.n));
  throws(() => {
    batch(() => {
      store.set({ n: 1 });
      throw new Error('boom');
    });
  }, 'boom');
  eq(seen, [1]);
  batch(() => store.set({ n: 2 }));
  eq(seen, [1, 2]);
});

// ──────────────────────────── tests ──────────────────────────────────────

// ── stage 1: static paths and the query string ───────────────────────────

test('matches a static path and returns its handler', () => {
  const router = createRouter();
  router.addRoute('/about', 'about');
  const found = router.match('/about');
  eq(found.handler, 'about');
  eq(found.params, {});
});

test('returns null when nothing matches', () => {
  const router = createRouter();
  router.addRoute('/about', 'about');
  eq(router.match('/contact'), null);
});

test('tells two static paths apart', () => {
  const router = createRouter();
  router.addRoute('/about', 'about');
  router.addRoute('/about/team', 'team');
  eq(router.match('/about/team').handler, 'team');
  eq(router.match('/about').handler, 'about');
});

test('a trailing slash does not change the route', () => {
  const router = createRouter();
  router.addRoute('/about', 'about');
  eq(router.match('/about/').handler, 'about');
  eq(router.match('about').handler, 'about');
});

test('parseQuery turns a search string into an object', () => {
  eq(parseQuery('a=1&b=2'), { a: '1', b: '2' });
  eq(parseQuery(''), {});
  eq(parseQuery('flag'), { flag: '' });
  eq(parseQuery('q=hello%20there'), { q: 'hello there' });
  eq(parseQuery('q=hello+there'), { q: 'hello there' });
});

test('match exposes the parsed query and an empty object without one', () => {
  const router = createRouter();
  router.addRoute('/search', 'search');
  eq(router.match('/search?q=cats&page=2').query, { q: 'cats', page: '2' });
  eq(router.match('/search').query, {});
});

// ── stage 2: :params ─────────────────────────────────────────────────────

test('captures a single :param', () => {
  const router = createRouter();
  router.addRoute('/users/:id', 'showUser');
  const found = router.match('/users/42');
  eq(found.handler, 'showUser');
  eq(found.params, { id: '42' });
});

test('captures several params in one pattern', () => {
  const router = createRouter();
  router.addRoute('/users/:userId/posts/:postId', 'showPost');
  eq(router.match('/users/7/posts/99').params, { userId: '7', postId: '99' });
});

test('params are strings, never numbers', () => {
  const router = createRouter();
  router.addRoute('/users/:id', 'showUser');
  eq(typeof router.match('/users/42').params.id, 'string');
});

test('a :param never swallows a slash', () => {
  const router = createRouter();
  router.addRoute('/files/:name', 'file');
  eq(router.match('/files/notes.txt').params, { name: 'notes.txt' });
  eq(router.match('/files/deep/notes.txt'), null);
});

test('param values are percent-decoded', () => {
  const router = createRouter();
  router.addRoute('/tags/:tag', 'tag');
  eq(router.match('/tags/data%20science').params, { tag: 'data science' });
});

test('params and query arrive together', () => {
  const router = createRouter();
  router.addRoute('/users/:id', 'showUser');
  const found = router.match('/users/42?tab=posts');
  eq(found.params, { id: '42' });
  eq(found.query, { tab: 'posts' });
});

// ── stage 3: precedence ──────────────────────────────────────────────────

test('a static segment beats a :param registered first', () => {
  const router = createRouter();
  router.addRoute('/users/:id', 'showUser');
  router.addRoute('/users/me', 'showMe');
  eq(router.match('/users/me').handler, 'showMe');
  eq(router.match('/users/42').handler, 'showUser');
});

test('the more specific pattern wins wherever the static part sits', () => {
  const router = createRouter();
  router.addRoute('/:type/:id', 'generic');
  router.addRoute('/users/:id', 'showUser');
  eq(router.match('/users/42').pattern, '/users/:id');
  eq(router.match('/posts/42').pattern, '/:type/:id');
});

test("'*' catches everything nothing else claimed", () => {
  const router = createRouter();
  router.addRoute('/about', 'about');
  router.addRoute('*', 'notFound');
  eq(router.match('/who/knows/where').handler, 'notFound');
  eq(router.match('/who/knows/where').params, {});
});

test("'*' never beats a route that really matches", () => {
  const router = createRouter();
  router.addRoute('*', 'notFound');
  router.addRoute('/about', 'about');
  router.addRoute('/users/:id', 'showUser');
  eq(router.match('/about').handler, 'about');
  eq(router.match('/users/1').handler, 'showUser');
});

test('the first registration wins a tie between equal patterns', () => {
  const router = createRouter();
  router.addRoute('/a/:x', 'first');
  router.addRoute('/a/:y', 'second');
  const found = router.match('/a/1');
  eq(found.handler, 'first');
  eq(found.params, { x: '1' });
});

// ── stage 4: buildPath (reverse routing) ─────────────────────────────────

test('buildPath fills params into a pattern', () => {
  eq(buildPath('/users/:id', { id: 'ada' }), '/users/ada');
  eq(buildPath('/users/:a/posts/:b', { a: '1', b: '2' }), '/users/1/posts/2');
});

test('buildPath stringifies non-strings', () => {
  eq(buildPath('/users/:id', { id: 7 }), '/users/7');
});

test('buildPath encodes characters that would break the URL', () => {
  eq(buildPath('/tags/:tag', { tag: 'data science' }), '/tags/data%20science');
  eq(buildPath('/tags/:tag', { tag: 'a/b' }), '/tags/a%2Fb');
});

test('buildPath throws when a param is missing', () => {
  const path = buildPath('/users/:id', { id: 1 });
  eq(path, '/users/1');
  throws(() => buildPath('/users/:id', {}), 'id');
});

test('leftover params become a query string', () => {
  eq(buildPath('/users/:id', { id: 1, tab: 'posts' }), '/users/1?tab=posts');
  eq(buildPath('/search', { q: 'cats' }), '/search?q=cats');
});

test('buildPath and match are inverses', () => {
  const router = createRouter();
  router.addRoute('/users/:userId/posts/:postId', 'showPost');
  const params = { userId: 'ada lovelace', postId: '99' };
  const url = buildPath('/users/:userId/posts/:postId', params);
  const found = router.match(url);
  ok(found !== null);
  eq(found.params, params);
});

// ──────────────────────────── tests ──────────────────────────────────────

// ── stage 1: {{interpolation}} ───────────────────────────────────────────

test('replaces a tag with the matching value', () => {
  eq(render('Hi {{name}}!', { name: 'Ada' }), 'Hi Ada!');
});

test('text without tags comes back unchanged', () => {
  eq(render('just words', { name: 'Ada' }), 'just words');
  eq(render('', {}), '');
});

test('resolves dot paths', () => {
  const data = { user: { profile: { city: 'Rome' } } };
  eq(render('{{user.profile.city}}', data), 'Rome');
});

test('a missing key renders as nothing, never "undefined"', () => {
  eq(render('[{{nope}}]', {}), '[]');
  eq(render('[{{a.b.c}}]', { a: {} }), '[]');
});

test('spaces inside the braces are allowed', () => {
  eq(render('{{ name }}', { name: 'Ada' }), 'Ada');
});

test('0 and false render, null and undefined render as nothing', () => {
  const data = { n: 0, flag: false, nil: null, un: undefined };
  eq(render('{{n}}|{{flag}}|{{nil}}|{{un}}', data), '0|false||');
});

// ── stage 2: escaping, and {{{raw}}} to opt out ──────────────────────────

test('escapeHtml handles the five characters that matter', () => {
  eq(escapeHtml('<a href="x">Tom & Jerry\'s</a>'),
    '&lt;a href=&quot;x&quot;&gt;Tom &amp; Jerry&#39;s&lt;/a&gt;');
});

test('values are escaped by default', () => {
  eq(render('{{bio}}', { bio: '<script>alert(1)</script>' }),
    '&lt;script&gt;alert(1)&lt;/script&gt;');
});

test('escaping happens once — & does not eat the other entities', () => {
  eq(render('{{s}}', { s: '<b>' }), '&lt;b&gt;');
  eq(render('{{s}}', { s: 'a & b' }), 'a &amp; b');
});

test('{{{triple}}} inserts the value untouched', () => {
  eq(render('{{{bio}}}', { bio: '<b>hi</b>' }), '<b>hi</b>');
  eq(render('{{{missing}}}', {}), '');
});

test('interpolate fills a fragment on its own', () => {
  eq(interpolate('hi {{name}}', { name: '<b>' }), 'hi &lt;b&gt;');
});

// ── stage 3: {{#if}} blocks ──────────────────────────────────────────────

test('an if block keeps its body when the value is truthy', () => {
  eq(render('{{#if admin}}danger{{/if}}', { admin: true }), 'danger');
});

test('an if block drops its body when the value is falsy', () => {
  eq(render('{{#if admin}}danger{{/if}}', { admin: false }), '');
  eq(render('{{#if admin}}danger{{/if}}', {}), '');
});

test('an empty array is falsy — "if there are items"', () => {
  eq(render('{{#if items}}some{{/if}}', { items: [] }), '');
  eq(render('{{#if items}}some{{/if}}', { items: [1] }), 'some');
});

test('the condition can be a dot path', () => {
  eq(render('{{#if user.admin}}hi{{/if}}', { user: { admin: true } }), 'hi');
});

test('text around and between blocks survives', () => {
  const out = render('A{{#if a}}B{{/if}}C{{#if b}}D{{/if}}E', { a: 1, b: 0 });
  eq(out, 'ABCE');
});

test('tags inside an if body are still interpolated', () => {
  eq(render('{{#if on}}v={{v}}{{/if}}', { on: true, v: 7 }), 'v=7');
});

// ── stage 4: {{#each}} blocks ────────────────────────────────────────────

test('each repeats its body once per item, with {{this}}', () => {
  eq(render('{{#each xs}}[{{this}}]{{/each}}', { xs: [1, 2, 3] }), '[1][2][3]');
});

test('{{@index}} is the position in the list', () => {
  eq(render('{{#each xs}}{{@index}}:{{this}} {{/each}}', { xs: ['a', 'b'] }),
    '0:a 1:b ');
});

test('object items expose their own fields', () => {
  const data = { rows: [{ name: 'ada' }, { name: 'grace' }] };
  eq(render('{{#each rows}}{{name}}/{{this.name}} {{/each}}', data),
    'ada/ada grace/grace ');
});

test('an empty list renders nothing at all', () => {
  eq(render('start{{#each xs}}x{{/each}}end', { xs: [] }), 'startend');
  eq(render('start{{#each xs}}x{{/each}}end', {}), 'startend');
});

test('the outer data is still readable inside the loop', () => {
  const data = { title: 'List', xs: ['a', 'b'] };
  eq(render('{{#each xs}}{{title}}:{{this}} {{/each}}', data), 'List:a List:b ');
});

test('blocks nest — an if inside an each', () => {
  const data = {
    items: [
      { label: 'a', done: true },
      { label: 'b', done: false },
    ],
  };
  const tpl = '{{#each items}}{{#if done}}[x] {{/if}}{{label}}; {{/each}}';
  eq(render(tpl, data), '[x] a; b; ');
});

// ──────────────────────────── tests ──────────────────────────────────────

// ── stage 1: run them all, in order ──────────────────────────────────────

test('resolves to the results in input order', async () => {
  const out = await runTasks([async () => 1, async () => 2, async () => 3]);
  eq(out, [1, 2, 3]);
});

test('input order wins even when later tasks finish first', async () => {
  const out = await runTasks([
    async () => {
      await sleep(25);
      return 'slow';
    },
    async () => 'fast',
  ]);
  eq(out, ['slow', 'fast']);
});

test('an empty task list resolves to an empty array', async () => {
  eq(await runTasks([]), []);
});

test('every task is called exactly once', async () => {
  const t = makeTracker();
  await runTasks([t.task('a'), t.task('b'), t.task('c')]);
  eq(t.started.length, 3);
  eq(t.finished.length, 3);
});

test('tasks that return a plain value work too', async () => {
  eq(await runTasks([() => 'plain', async () => 'async']), ['plain', 'async']);
});

// ── stage 2: concurrency ─────────────────────────────────────────────────

test('never runs more than `concurrency` tasks at once', async () => {
  const t = makeTracker();
  const tasks = ['a', 'b', 'c', 'd', 'e', 'f'].map((v) => t.task(v));
  await runTasks(tasks, { concurrency: 2 });
  eq(t.maxInFlight, 2);
  eq(t.finished.length, 6);
});

test('concurrency 1 runs the tasks strictly one after another', async () => {
  const t = makeTracker();
  const out = await runTasks([t.task('a'), t.task('b'), t.task('c')], {
    concurrency: 1,
  });
  eq(t.maxInFlight, 1);
  eq(t.finished, ['a', 'b', 'c']);
  eq(out, ['a', 'b', 'c']);
});

test('a limit larger than the list is harmless', async () => {
  const t = makeTracker();
  const out = await runTasks([t.task('a'), t.task('b')], { concurrency: 10 });
  eq(t.maxInFlight, 2);
  eq(out, ['a', 'b']);
});

test('a free slot is refilled before the slow task finishes', async () => {
  const t = makeTracker();
  const g = gate();
  const c = t.task('c', 1);
  // 'slow' keeps its slot until 'c' has finished, so this finish order is
  // reachable only if the runner refilled the OTHER slot while slow was
  // still in flight. Chunk the array instead and c never gets to run.
  const tasks = [
    t.gated('slow', g.wait),
    t.task('b', 1),
    async () => {
      const value = await c();
      g.open();
      return value;
    },
  ];
  const out = await runTasks(tasks, { concurrency: 2 });
  eq(t.maxInFlight, 2);
  eq(t.finished, ['b', 'c', 'slow']);
  eq(out, ['slow', 'b', 'c']);
});

test('the default is no limit at all', async () => {
  const t = makeTracker();
  const tasks = ['a', 'b', 'c', 'd'].map((v) => t.task(v));
  await runTasks(tasks);
  eq(t.maxInFlight, 4);
});

// ── stage 3: retry and withTimeout ───────────────────────────────────────

test('retry leaves a task that works alone', async () => {
  let attempts = 0;
  const wrapped = retry(
    async () => {
      attempts += 1;
      return 'ok';
    },
    { times: 3 }
  );
  eq(await wrapped(), 'ok');
  eq(attempts, 1);
});

test('retry keeps going until an attempt succeeds', async () => {
  let attempts = 0;
  const flaky = async () => {
    attempts += 1;
    if (attempts < 3) throw new Error('flaky');
    return 'ok';
  };
  const wrapped = retry(flaky, { times: 5 });
  eq(await wrapped(), 'ok');
  eq(attempts, 3);
});

test('retry gives up after `times` attempts, rejecting with the last error',
  async () => {
    let attempts = 0;
    const always = async () => {
      attempts += 1;
      throw new Error(`nope ${attempts}`);
    };
    const wrapped = retry(always, { times: 3 });
    await rejects(wrapped, 'nope 3');
    eq(attempts, 3);
  });

test('times: 1 means one attempt and no retry', async () => {
  let attempts = 0;
  const always = async () => {
    attempts += 1;
    throw new Error('nope');
  };
  const wrapped = retry(always, { times: 1 });
  await rejects(wrapped, 'nope');
  eq(attempts, 1);
});

test('withTimeout resolves when the task is fast enough', async () => {
  const wrapped = withTimeout(async () => {
    await sleep(1);
    return 'quick';
  }, 200);
  eq(await wrapped(), 'quick');
});

test('withTimeout rejects when the task takes too long', async () => {
  const wrapped = withTimeout(async () => {
    await sleep(60); // six times the limit — no photo finish to lose
    return 'late';
  }, 10);
  await rejects(wrapped, /timed out/);
});

test("withTimeout passes the task's own error through unchanged", async () => {
  const wrapped = withTimeout(failing('boom', 1), 200);
  await rejects(wrapped, 'boom');
});

// ── stage 4: collectErrors, and composing the three ──────────────────────

test('collectErrors reports settled records, like allSettled', async () => {
  const results = await runTasks([async () => 1, failing('boom')], {
    collectErrors: true,
  });
  eq(results[0], { status: 'fulfilled', value: 1 });
  eq(results[1].status, 'rejected');
  eq(results[1].reason.message, 'boom');
});

test('settled records keep the input order', async () => {
  const results = await runTasks([failing('first', 20), async () => 'second'], {
    collectErrors: true,
  });
  eq(results.map((r) => r.status), ['rejected', 'fulfilled']);
});

test('one failing task does not stop the others', async () => {
  const t = makeTracker();
  const tasks = [t.task('a'), failing('boom'), t.task('c')];
  const results = await runTasks(tasks, { collectErrors: true, concurrency: 2 });
  eq(t.finished.length, 2);
  eq(results.map((r) => r.status), ['fulfilled', 'rejected', 'fulfilled']);
});

test('without collectErrors the first failure rejects the whole run', async () => {
  const tasks = [failing('boom'), async () => 'fine'];
  const settled = await runTasks(tasks, { collectErrors: true });
  eq(settled.map((r) => r.status), ['rejected', 'fulfilled']);
  await rejects(() => runTasks(tasks), 'boom');
});

test('retry composes with the pool — only the last failure is recorded',
  async () => {
    let attempts = 0;
    const always = async () => {
      attempts += 1;
      throw new Error('always');
    };
    const results = await runTasks(
      [retry(always, { times: 3 }), async () => 'ok'],
      { collectErrors: true }
    );
    eq(attempts, 3);
    eq(results[0].reason.message, 'always');
    eq(results[1].value, 'ok');
  });

test('pool + retry + timeout, all three together', async () => {
  let attempts = 0;
  const slowThenFast = async () => {
    attempts += 1;
    if (attempts === 1) await sleep(60); // first attempt blows the limit,
    return 'recovered'; //                  the retry settles right away
  };
  const task = retry(withTimeout(slowThenFast, 10), { times: 3 });
  const out = await runTasks([task, async () => 'plain'], { concurrency: 2 });
  eq(out, ['recovered', 'plain']);
  eq(attempts, 2);
});

