// ──────────────────────────── tests ──────────────────────────────────────

// ── stage 1: paragraphs and headings ─────────────────────────────────────

test('a plain line becomes a paragraph', () => {
  eq(mdToHtml('hello there'), '<p>hello there</p>');
});

test('#, ## and ### become h1, h2 and h3', () => {
  eq(mdToHtml('# One'), '<h1>One</h1>');
  eq(mdToHtml('## Two'), '<h2>Two</h2>');
  eq(mdToHtml('### Three'), '<h3>Three</h3>');
});

test('#### is not a heading — h1 to h3 only', () => {
  eq(mdToHtml('#### Four'), '<p>#### Four</p>');
});

test('a blank line starts a new paragraph', () => {
  eq(mdToHtml('one\n\ntwo'), '<p>one</p>\n<p>two</p>');
});

test('consecutive lines join into one paragraph', () => {
  eq(mdToHtml('one\ntwo\nthree'), '<p>one two three</p>');
});

test('empty input and stray blank lines produce nothing', () => {
  eq(mdToHtml(''), '');
  eq(mdToHtml('\n\n\n'), '');
  eq(mdToHtml('\n\nhi\n\n'), '<p>hi</p>');
});

// ── stage 2: inline markup ───────────────────────────────────────────────

test('**bold** becomes strong', () => {
  eq(mdToHtml('say **loudly** now'), '<p>say <strong>loudly</strong> now</p>');
});

test('*italic* becomes em', () => {
  eq(mdToHtml('say *softly* now'), '<p>say <em>softly</em> now</p>');
});

test('`code` becomes a code span', () => {
  eq(mdToHtml('run `npm test` now'), '<p>run <code>npm test</code> now</p>');
});

test('[text](url) becomes a link', () => {
  eq(mdToHtml('see [the docs](/docs) now'),
    '<p>see <a href="/docs">the docs</a> now</p>');
});

test('bold is not parsed as two italics', () => {
  eq(renderInline('**a**'), '<strong>a</strong>');
  eq(renderInline('*a*'), '<em>a</em>');
  eq(renderInline('**a** and *b*'), '<strong>a</strong> and <em>b</em>');
});

test('inline markup works inside a heading', () => {
  eq(mdToHtml('## The **big** one'), '<h2>The <strong>big</strong> one</h2>');
});

// ── stage 3: lists ───────────────────────────────────────────────────────

test('a single "- " line becomes a one-item list', () => {
  eq(mdToHtml('- alone'), '<ul><li>alone</li></ul>');
});

test('consecutive items collapse into one list', () => {
  eq(mdToHtml('- one\n- two\n- three'),
    '<ul><li>one</li><li>two</li><li>three</li></ul>');
});

test('a blank line ends the list, so a second list is a second ul', () => {
  eq(mdToHtml('- one\n\n- two'),
    '<ul><li>one</li></ul>\n<ul><li>two</li></ul>');
});

test('inline markup works inside list items', () => {
  eq(mdToHtml('- a **b** [c](/d)'),
    '<ul><li>a <strong>b</strong> <a href="/d">c</a></li></ul>');
});

test('a paragraph right after a list is a separate block', () => {
  eq(mdToHtml('- one\nafter'), '<ul><li>one</li></ul>\n<p>after</p>');
});

// ── stage 4: escaping and the tricky interactions ────────────────────────

test('escapeHtml turns the dangerous characters into entities', () => {
  eq(escapeHtml('<b>&</b>'), '&lt;b&gt;&amp;&lt;/b&gt;');
});

test('raw HTML in the source is escaped, not passed through', () => {
  eq(mdToHtml('<script>alert(1)</script>'),
    '<p>&lt;script&gt;alert(1)&lt;/script&gt;</p>');
});

test('& becomes &amp; exactly once', () => {
  eq(mdToHtml('AT&T'), '<p>AT&amp;T</p>');
});

test('a star inside a code span stays a literal star', () => {
  eq(mdToHtml('use `a * b` here'), '<p>use <code>a * b</code> here</p>');
  eq(mdToHtml('`**not bold**`'), '<p><code>**not bold**</code></p>');
});

test('angle brackets inside a code span are escaped', () => {
  eq(mdToHtml('`<div>`'), '<p><code>&lt;div&gt;</code></p>');
});

test('link text is escaped but the anchor still works', () => {
  eq(mdToHtml('[a<b](/x)'), '<p><a href="/x">a&lt;b</a></p>');
});

test('a whole small document', () => {
  const md = [
    '# Title',
    '',
    'Hello **world** and `code`.',
    '',
    '- one',
    '- two *emph*',
    '',
    'See [docs](/docs).',
  ].join('\n');
  const html = [
    '<h1>Title</h1>',
    '<p>Hello <strong>world</strong> and <code>code</code>.</p>',
    '<ul><li>one</li><li>two <em>emph</em></li></ul>',
    '<p>See <a href="/docs">docs</a>.</p>',
  ].join('\n');
  eq(mdToHtml(md), html);
});

// ──────────────────────────── tests ──────────────────────────────────────

// ── stage 1: it + run ────────────────────────────────────────────────────

test('run reports a passing test', () => {
  it('works', () => {});
  const report = run();
  eq(report.passed, 1);
  eq(report.failed, 0);
  eq(report.failures, []);
});

test('a test that throws is counted as a failure', () => {
  it('breaks', () => {
    throw new Error('nope');
  });
  const report = run();
  eq(report.passed, 0);
  eq(report.failed, 1);
});

test('a failure carries the test name and the message', () => {
  it('breaks', () => {
    throw new Error('nope');
  });
  eq(run().failures, [{ path: 'breaks', message: 'nope' }]);
});

test('passes and failures are counted together', () => {
  it('a', () => {});
  it('b', () => {
    throw new Error('x');
  });
  it('c', () => {});
  const report = run();
  eq(report.passed, 2);
  eq(report.failed, 1);
});

test('running nothing reports zeroes', () => {
  eq(run(), { passed: 0, failed: 0, failures: [] });
});

test('run clears the collected tests', () => {
  it('once', () => {});
  eq(run().passed, 1);
  eq(run().passed, 0);
});

// ── stage 2: expect, toBe and toEqual ────────────────────────────────────

test('toBe passes on equal primitives and fails on different ones', () => {
  it('same', () => expect(1).toBe(1));
  it('different', () => expect(1).toBe(2));
  const report = run();
  eq(report.passed, 1);
  eq(report.failed, 1);
  eq(report.failures[0].message, 'expected 2 but got 1');
});

test('toBe compares with Object.is, so NaN equals NaN', () => {
  it('nan', () => expect(NaN).toBe(NaN));
  it('zeroes', () => expect(0).toBe(-0));
  const report = run();
  eq(report.passed, 1);
  eq(report.failed, 1);
});

test('toBe fails for two structurally equal objects', () => {
  it('objects', () => expect({ a: 1 }).toBe({ a: 1 }));
  eq(run().failed, 1);
});

test('toEqual passes for deeply equal structures', () => {
  it('deep', () => expect({ a: [1, { b: 2 }] }).toEqual({ a: [1, { b: 2 }] }));
  eq(run().passed, 1);
});

test('a toEqual failure shows both values', () => {
  it('deep', () => expect({ a: 1 }).toEqual({ a: 2 }));
  eq(run().failures[0].message, 'expected {"a":2} but got {"a":1}');
});

test('deepEqual handles nesting, lengths and key counts', () => {
  eq(deepEqual([1, [2, 3]], [1, [2, 3]]), true);
  eq(deepEqual([1, 2], [1, 2, 3]), false);
  eq(deepEqual({ a: 1 }, { a: 1, b: undefined }), false);
  eq(deepEqual(null, null), true);
  eq(deepEqual(null, {}), false);
  eq(deepEqual('1', 1), false);
});

// ── stage 3: describe and the failure path ───────────────────────────────

test('a describe name is part of the path', () => {
  describe('math', () => {
    it('adds', () => {
      throw new Error('x');
    });
  });
  eq(run().failures[0].path, 'math > adds');
});

test('describes nest as deep as you like', () => {
  describe('a', () => {
    describe('b', () => {
      it('c', () => {
        throw new Error('x');
      });
    });
  });
  eq(run().failures[0].path, 'a > b > c');
});

test('sibling describes keep their own paths', () => {
  describe('a', () =>
    it('x', () => {
      throw new Error('1');
    }));
  describe('b', () =>
    it('x', () => {
      throw new Error('2');
    }));
  eq(run().failures.map((f) => f.path), ['a > x', 'b > x']);
});

test('a suite runs its own tests before its nested suites', () => {
  const order = [];
  describe('outer', () => {
    it('own 1', () => order.push('own 1'));
    describe('inner', () => {
      it('nested', () => order.push('nested'));
    });
    it('own 2', () => order.push('own 2'));
  });
  run();
  eq(order, ['own 1', 'own 2', 'nested']);
});

test('an empty describe contributes nothing', () => {
  describe('empty', () => {});
  eq(run(), { passed: 0, failed: 0, failures: [] });
});

// ── stage 4: toThrow, and surviving rude tests ───────────────────────────

test('toThrow passes when the function throws', () => {
  it('throws', () =>
    expect(() => {
      throw new Error('boom');
    }).toThrow());
  eq(run().passed, 1);
});

test('toThrow fails when nothing is thrown', () => {
  it('quiet', () => expect(() => 'fine').toThrow());
  const report = run();
  eq(report.failed, 1);
  eq(report.failures[0].message, 'expected the function to throw');
});

test('toThrow can require a substring of the message', () => {
  const boom = () => {
    throw new Error('boom town');
  };
  it('match', () => expect(boom).toThrow('boom'));
  it('mismatch', () => expect(boom).toThrow('bang'));
  const report = run();
  eq(report.passed, 1);
  eq(report.failed, 1);
  eq(report.failures[0].message,
    'expected the error to match bang, got: boom town');
});

test('toThrow accepts a RegExp too', () => {
  it('regex', () =>
    expect(() => {
      throw new Error('code 42');
    }).toThrow(/\d+/));
  eq(run().passed, 1);
});

test('one failing test does not stop the ones after it', () => {
  const ran = [];
  it('one', () => {
    ran.push('one');
    throw new Error('x');
  });
  it('two', () => ran.push('two'));
  it('three', () => {
    ran.push('three');
    throw new Error('y');
  });
  const report = run();
  eq(ran, ['one', 'two', 'three']);
  eq(report.passed, 1);
  eq(report.failed, 2);
});

test('a test that throws a non-Error is still reported', () => {
  it('rude', () => {
    throw 'just a string';
  });
  const report = run();
  eq(report.failed, 1);
  eq(report.failures[0].message, 'just a string');
});

// ──────────────────────────── tests ──────────────────────────────────────

// ── stage 1: parsePath + getPath ─────────────────────────────────────────

test('parsePath splits a dotted path', () => {
  eq(parsePath('a.b.c'), ['a', 'b', 'c']);
});

test('parsePath turns [0] into a real number', () => {
  eq(parsePath('a.b[0].c'), ['a', 'b', 0, 'c']);
});

test('parsePath handles leading and consecutive indexes', () => {
  eq(parsePath('[0][1]'), [0, 1]);
  eq(parsePath('grid[2][3].value'), ['grid', 2, 3, 'value']);
});

test('parsePath passes an array path straight through', () => {
  eq(parsePath(''), []);
  const keys = ['a', 0];
  ok(parsePath(keys) === keys);
});

test('getPath walks objects and arrays', () => {
  const data = { a: { b: [{ c: 7 }, { c: 8 }] } };
  eq(getPath(data, 'a.b[0].c'), 7);
  eq(getPath(data, 'a.b[1].c'), 8);
  eq(getPath(data, 'a.b').length, 2);
});

// ── stage 2: safe reads ──────────────────────────────────────────────────

test('a missing key reads as undefined', () => {
  eq(getPath({ a: 1 }, 'b'), undefined);
});

test('the fallback is used when the path leads nowhere', () => {
  eq(getPath({ a: 1 }, 'b.c.d', 'none'), 'none');
  eq(getPath({}, 'a[3].b', 'none'), 'none');
});

test('a null halfway down does not throw', () => {
  eq(getPath({ a: null }, 'a.b.c', 'none'), 'none');
  eq(getPath(null, 'a', 'none'), 'none');
  eq(getPath(undefined, 'a.b', 'none'), 'none');
});

test('an existing null wins over the fallback', () => {
  eq(getPath({ a: null }, 'a', 'none'), null);
});

test('falsy values are returned, not replaced', () => {
  const data = { zero: 0, empty: '', no: false };
  eq(getPath(data, 'zero', 'none'), 0);
  eq(getPath(data, 'empty', 'none'), '');
  eq(getPath(data, 'no', 'none'), false);
});

test('reading through a primitive is safe too', () => {
  eq(getPath(42, 'a.b', 'none'), 'none');
  eq(getPath('text', 'length'), 4);
});

// ── stage 3: setPath, immutably ──────────────────────────────────────────

test('setPath returns a new object with the value set', () => {
  const before = { a: { b: 1 } };
  const after = setPath(before, 'a.b', 2);
  eq(after, { a: { b: 2 } });
  eq(before, { a: { b: 1 } });
  ok(after !== before);
});

test('branches you did not touch keep their identity', () => {
  const before = { keep: { deep: [1, 2] }, edit: { x: 1 } };
  const after = setPath(before, 'edit.x', 2);
  ok(after.keep === before.keep);
  ok(after.edit !== before.edit);
  eq(after.edit.x, 2);
});

test('every container on the path is a fresh one', () => {
  const before = { a: { b: { c: 1 } } };
  const after = setPath(before, 'a.b.c', 2);
  ok(after.a !== before.a);
  ok(after.a.b !== before.a.b);
});

test('missing objects are created along the way', () => {
  eq(setPath({}, 'a.b.c', 1), { a: { b: { c: 1 } } });
  eq(setPath({ a: 1 }, 'b.c', 2), { a: 1, b: { c: 2 } });
});

test('a numeric key creates an array, not an object', () => {
  const made = setPath({}, 'list[0].name', 'ada');
  eq(made, { list: [{ name: 'ada' }] });
  ok(Array.isArray(made.list));
});

test('writing inside an array keeps it an array', () => {
  const before = { xs: [1, 2, 3] };
  const after = setPath(before, 'xs[1]', 9);
  eq(after, { xs: [1, 9, 3] });
  ok(Array.isArray(after.xs));
  ok(after.xs !== before.xs);
  eq(before.xs, [1, 2, 3]);
});

test('writing the value that is already there changes nothing', () => {
  const before = { a: { b: 1 } };
  ok(setPath(before, 'a.b', 1) === before);
});

test('setPath refuses to write through __proto__', () => {
  const safe = setPath({}, 'a.b', 1);
  eq(safe, { a: { b: 1 } });
  throws(() => setPath({}, '__proto__.polluted', 1), '__proto__');
  eq({}.polluted, undefined);
});

// ── stage 4: deletePath and select ───────────────────────────────────────

test('deletePath removes a key without mutating', () => {
  const before = { a: { b: 1, c: 2 }, keep: { x: 1 } };
  const after = deletePath(before, 'a.b');
