  eq(history.size(), 1);
});

test('the limit drops the oldest entry, not the newest', () => {
  const doc = makeDoc();
  const history = new UndoManager({ limit: 3 });
  for (const ch of 'abcde') history.execute(doc.type(ch));
  eq(doc.text, 'abcde');
